/* A staged cargo push and pullback share the shot clock, with separate depth factors. */
export const depotEase=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)};
const mix=(a,b,q)=>a+(b-a)*q;
export function depotState(age,f){const descent=depotEase(age/Math.max(.1,f.depotDescent)),push=depotEase((age-(f.depotCargoPushStart??f.depotDescent))/Math.max(.1,f.depotCargoPushTime??4)),pull=depotEase((age-f.depotPullStart)/Math.max(.1,f.depotPullTime));return {descent,push,pull,outgoingY:-540*descent,incomingY:540*(1-descent),actorScale:mix(f.depotStartScale,f.depotEndScale,pull),backScale:mix(f.depotBackgroundStart,1,pull),cargoBackScale:mix(f.depotCargoBackScale??1.4,1,push),midScale:mix(f.depotCargoMidScale??1.85,1,push),nearScale:mix(f.depotCargoNearScale??2.6,1,push),frontScale:f.depotCargoFrontEnd??1.6,focusX:mix(f.depotStartFocusX??f.depotFocusX,f.depotFocusX,pull),focusY:mix(f.depotStartFocusY??f.depotFocusY,f.depotFocusY,pull),roomBlur:mix(f.depotBlurStart,f.depotBlurEnd,depotEase((age-f.depotDescent)/Math.max(.1,f.depotFocusTime))),smoke:1-depotEase(age/Math.max(.1,f.depotSmokeClear))}}
export function depotPlacement(object,state,f){const depth=object.depth||'people',base=depth==='front'?state.frontScale:depth==='near'?state.nearScale:depth==='mid'?state.midScale:depth==='back'?state.cargoBackScale:state.actorScale,scale=1+(base-1)*(object.depthStrength??1),focusX=state.focusX,focusY=object.type==='crate'?(f.depotFloorY??540):state.focusY;return {x:focusX+(object.x-focusX)*scale,y:object.type==='crate'?object.y+object.height*.44-object.height*.44*scale:focusY+(object.y-focusY)*scale,scale,rotation:object.rotation||0}}
export function depotEnvelope(age,o){return o.visible===false?0:(o.opacity??1)*depotEase((age-(o.start||0))/Math.max(.1,o.fade||1))}
export function depotPhase(d,f){const overlap=Math.max(0,Math.min(Number(f.depotDescent)||5,Number(f.battleDuration)||26));return {...d,depot:d.images-overlap,images:d.images+Number(f.depotDuration)-overlap,end:d.end+Number(f.depotDuration)-overlap}}
